Mashup.mashupContent:
{ "CustomMashupCss": "/* Shared Git workspace tokens and layout.

 Spacing rule: every visible widget keeps ThingWorx's default Margin of 5,
 so neighbouring controls sit 10px apart. Card containers also use Margin 5
 so their edges line up with text. Container padding and gaps below subtract
 that 5px, so the visible insets are 24px at the page edge and 16px between
 sections and inside cards. Do not give individual widgets other margins;
 align rows with the container's align-items instead (flex-end for rows with
 labelled inputs, center for buttons and checkboxes).

 Contrast (WCAG): text 11.4:1 and muted text 5.2:1 on the canvas; muted text
 5.9:1 on surfaces. Native widget colors and focus indicators stay with the
 active ThingWorx theme. The theme's container style sets a white
 background, so backgrounds and borders below need !important. */
:root {
 --git-text: #243746;
 --git-muted: #536776;
 --git-canvas: #eef1f4;
 --git-surface: #ffffff;
 --git-border: #c2cbd3;
 --git-radius: 6px;
 --git-page-inset: 19px; /* + 5px widget margin = 24px */
 --git-card-inset: 11px; /* + 5px widget margin = 16px */
 --git-section-gap: 6px; /* + 5px + 5px margins = 16px */
 --git-header-height: 64px;
}

/* Header band: the slot that holds GIT.Mashup.GitHeader on every page. The
 runtime sizes a contained mashup to fill its slot, so GitHeader applies its
 own horizontal inset (see GitHeader.css). */
[id$="git-header-slot"] {
 min-height: var(--git-header-height);
 background: var(--git-surface) !important;
 border-bottom: 1px solid var(--git-border) !important;
 color: var(--git-text);
 box-sizing: border-box;
}

/* Page body. */
[id$="home-main"],
[id$="changes-main"],
[id$="branches-main"],
[id$="history-main"],
[id$="log-main"],
[id$="reflog-main"], [id$="repository-main"],
[id$="extlog-main"],
[id$="settings-main"],
[id$="create-main"],
[id$="user-settings-content"],
[id$="operations-main"],
[id$="conflictresolution-main"] {
 padding: var(--git-page-inset);
 gap: var(--git-section-gap);
 align-items: stretch !important;
 background: var(--git-canvas) !important;
 color: var(--git-text);
 box-sizing: border-box;
}

/* Layout containers inside the page stay transparent; only cards are white. */
:is([id$="home-main"], [id$="changes-main"], [id$="branches-main"], [id$="history-main"], [id$="log-main"], [id$="reflog-main"], [id$="repository-main"], [id$="extlog-main"], [id$="settings-main"], [id$="create-main"], [id$="user-settings-content"], [id$="operations-main"], [id$="conflictresolution-main"]) .widget-flexcontainer { background: transparent !important; }

/* Cards: white surfaces on the canvas. */
:is([id$="home-main"], [id$="changes-main"], [id$="branches-main"], [id$="history-main"], [id$="log-main"], [id$="reflog-main"], [id$="repository-main"], [id$="extlog-main"], [id$="settings-main"], [id$="create-main"], [id$="user-settings-content"], [id$="operations-main"], [id$="conflictresolution-main"]) :is([id$="home-list-container"], [id$="repository-readme-card"], [id$="changes-sync-card"], [id$="changes-worktree-card"], [id$="changes-push-card"], [id$="branches-list-card"], [id$="branches-create-card"], [id$="branches-merge-card"], [id$="repository-settings-card"], [id$="repository-credentials-card"], [id$="repository-status-card"], [id$="settings-projects"], [id$="settings-projects-add"], [id$="settings-delete"], [id$="settings-remotes"], [id$="create-repository-card"], [id$="create-credentials-card"], [id$="create-projects-card"], [id$="create-advanced-card"], [id$="history-tree-card"], [id$="history-log-card"]),
[id$="user-settings-content"] :is([id$="flexcontainer-40"], [id$="flexcontainer-41"], [id$="ssh-keys-section"], [id$="ssh-add-section"], [id$="identity-section"], [id$="extension-log-section"]) {
 background: var(--git-surface) !important;
 border: 1px solid var(--git-border) !important;
 border-radius: var(--git-radius) !important;
 box-sizing: border-box;
 min-width: 0;
}
/* User Settings sections use the shared card inset. */
[id$="user-settings-content"] :is([id$="flexcontainer-40"], [id$="flexcontainer-41"], [id$="ssh-keys-section"], [id$="ssh-add-section"], [id$="identity-section"], [id$="extension-log-section"]) { padding: var(--git-card-inset); }

/* One scroller per page: the *-main body. The runtime gives every bounding box
 min-height: 0 and container bounding boxes max-height: 100%, so on a short
 viewport (e.g. 150% display scaling) cards shrink and each grows its own
 scrollbar. Keep the body's direct children at their content height instead. */
:is([id$="home-main"], [id$="changes-main"], [id$="branches-main"], [id$="history-main"], [id$="log-main"], [id$="reflog-main"], [id$="repository-main"], [id$="extlog-main"], [id$="settings-main"], [id$="create-main"], [id$="user-settings-content"], [id$="operations-main"], [id$="conflictresolution-main"]) > .widget-bounding-box { flex-shrink: 0 !important; max-height: none !important; }

/* Grid areas: the grid draws its own border, so only size them. */
[id$="changes-grid-area"],
[id$="branches-grid-area"],
[id$="log-grid-area"],
[id$="reflog-grid-area"],
[id$="extlog-grid-area"] { min-height: 320px; min-width: 0; }
[id$="changes-grid-bounding-box"],
[id$="log-grid-bounding-box"],
[id$="reflog-grid-bounding-box"],
[id$="extlog-grid-bounding-box"] { position: relative; flex: 1 1 0%; min-width: 0; }

/* Secondary text. */
[id$="-intro"],
[id$="-status"] { color: var(--git-muted); line-height: 1.5; }

@media (max-width: 600px) {
 :root { --git-page-inset: 11px; } /* 16px visible */
}

/* Tags card (src/TagControls.ts) on History and Changes. */
[id$="tagcontrols-helper-bounding-box"] {
 position: relative;
 align-self: stretch;
 width: 100% !important;
 min-width: 0;
}
.git-tag-controls {
 padding: 0.75rem;
 box-sizing: border-box;
 width: 100%;
 height: 100%;
 overflow: auto;
 color: var(--git-text);
 font-family: Arial, Helvetica, sans-serif;
 font-size: 14px;
 line-height: 1.4;
}
.git-tag-controls h2 { margin: 0 0 0.5rem; font-size: 1.1rem; }
.git-tag-row { display: flex; flex-wrap: wrap; align-items: flex-end; gap: 0.5rem; margin: 0.25rem 0; }
.git-tag-row label { display: flex; flex-direction: column; gap: 0.25rem; }
.git-tag-row label.git-tag-check { flex-direction: row; align-items: center; min-height: 34px; }
.git-tag-controls input[type="text"],
.git-tag-controls select {
 min-height: 34px;
 min-width: 12rem;
 padding: 0 0.5rem;
 font: inherit;
 color: var(--git-text);
 background: var(--git-surface);
 border: 1px solid var(--git-border);
 border-radius: 3px;
}
.git-tag-controls button {
 min-height: 34px;
 padding: 0.5rem 1rem;
 font: inherit;
 color: #fff;
 background: #0073aa;
 border: 1px solid #0073aa;
 border-radius: 3px;
 cursor: pointer;
}
.git-tag-controls button:hover:not(:disabled) { background: #005d89; }
.git-tag-controls button:disabled { opacity: 0.55; cursor: default; }
.git-tag-controls button:focus-visible,
.git-tag-controls input:focus-visible,
.git-tag-controls select:focus-visible { outline: 2px solid #0073aa; outline-offset: 2px; }
.git-tag-list[hidden] { display: none; }
.git-tag-list table { width: 100%; border-collapse: collapse; margin: 0.5rem 0; }
.git-tag-list th, .git-tag-list td { padding: 0.35rem 0.5rem; text-align: left; border-bottom: 1px solid var(--git-border); }
.git-tag-list td:nth-child(3) { font-family: monospace; }
.git-tag-controls p { margin: 0.25rem 0; color: var(--git-muted); white-space: pre-wrap; overflow-wrap: anywhere; }", "Data": { "Session": { "DataName": "Session", "EntityName": "", "EntityType": "Session", "Id": "session", "Services": [ { "APIMethod": "post", "Characteristic": "Services", "Id": "SessionInterface", "Name": "GetGlobalSessionValues", "Parameters": {}, "RefreshInterval": 0, "Target": "GetGlobalSessionValues" } ] }, "Things_GIT.Utility.Thing": { "DataName": "Things_GIT.Utility.Thing", "EntityName": "GIT.Utility.Thing", "EntityType": "Things", "Id": "c741fde6-86d0-47ea-a69e-4faaed59ad7a", "RefreshInterval": 0, "Services": [ { "APIMethod": "post", "Caching": { "cache": false, "cacheKeyParams": [], "cacheStrategy": "INSTANCE", "maxResultSets": "10" }, "Characteristic": "Services", "Id": "4e7b452e-eb35-4e51-9965-2ff19e38e16a", "Name": "GitCredentialGet", "Parameters": {}, "RefreshInterval": 0, "Target": "GitCredentialGet" }, { "APIMethod": "post", "Caching": { "cache": false, "cacheKeyParams": [], "cacheStrategy": "INSTANCE", "maxResultSets": "10" }, "Characteristic": "Services", "Id": "368d25c7-848b-4d16-8fdf-423b7be63362", "Name": "GitCredentialUpdate", "Parameters": {}, "RefreshInterval": 0, "Target": "GitCredentialUpdate" }, { "APIMethod": "post", "Caching": { "cache": false, "cacheKeyParams": [], "cacheStrategy": "INSTANCE", "maxResultSets": "10" }, "Characteristic": "Services", "Id": "1548704e-b344-4341-a2bf-c501e3f88708", "Name": "VerifyGpgKey", "Parameters": {}, "RefreshInterval": 0, "Target": "VerifyGpgKey" }, { "APIMethod": "post", "Caching": { "cache": false, "cacheKeyParams": [], "cacheStrategy": "INSTANCE", "maxResultSets": "10" }, "Characteristic": "Services", "Id": "b697aeae-fd9f-4dca-9ab9-a4ddbb300c10", "Name": "GpgKeyUpdate", "Parameters": {}, "RefreshInterval": 0, "Target": "GpgKeyUpdate" }, { "APIMethod": "post", "Caching": { "cache": false, "cacheKeyParams": [], "cacheStrategy": "INSTANCE", "maxResultSets": "10" }, "Characteristic": "Ser